    }
  ],
  "dataModel": {
    "value": {
      "data": {
        "calendar": {
          "items": [
            {
              "entityName": "calendar",
              "entityId": "mock-meeting-001",
              "title": "项目同步会",
              "eventLocation": "A座 301",
              "dtStart": "14:00",
              "dtEnd": "15:00"
            }
          ]
        },
        "room": {
          "name": "A座 301",
          "occupancyText": "空闲中",
